const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim();
const n = Number(input);

const dp = new Int32Array(n + 1);
for (let i = 1; i <= n; i++) {
  let x = i;
  let best = Infinity;
  while (x > 0) {
    const digit = x % 10;
    if (digit > 0) best = Math.min(best, dp[i - digit] + 1);
    x = Math.floor(x / 10);
  }
  dp[i] = best;
}

console.log(dp[n]);
